"""Seleção, divisão por seções e extração de links de arquivos Markdown."""

import fnmatch
import hashlib
import posixpath
import re
import unicodedata
from dataclasses import dataclass, field
from urllib.parse import unquote

EXTENSOES = (".md", ".markdown")
DIRETORIOS_DEPENDENCIA = {
    "node_modules",
    "vendor",
    "bower_components",
    ".venv",
    "venv",
    "env",
    "site-packages",
    "dist",
    "build",
    "target",
    "third_party",
    "__pycache__",
    ".tox",
    ".git",
    ".github",
}
MARCADORES_GERADO = (
    "<!-- generated",
    "auto-generated",
    "autogenerated",
    "this file was generated",
    "this file is generated",
    "do not edit",
    "gerado automaticamente",
    "não edite",
)
TERMOS_PLACEHOLDER = (
    "todo",
    "tbd",
    "em breve",
    "coming soon",
    "lorem ipsum",
    "placeholder",
    "work in progress",
    "add a description",
    "descrição do projeto",
)
MIN_PALAVRAS_UTEIS = 8
MIN_PALAVRAS_SEM_PLACEHOLDER = 25
MAX_CARACTERES_SECAO = 2500
LIMITE_BYTES = 512 * 1024

_CERCA = re.compile(r"^\s{0,3}(`{3,}|~{3,})")
_TITULO = re.compile(r"^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$")
_LINK = re.compile(r"(?<!!)\[([^\]]*)\]\(\s*<?([^)\s>]+)>?(?:\s+\"[^\"]*\")?\s*\)")
_REF_DEF = re.compile(r"^\s{0,3}\[[^\]]+\]:\s*<?(\S+?)>?(?:\s+\"[^\"]*\")?\s*$")
_GITHUB_BLOB = re.compile(
    r"^https?://github\.com/(?P<conta>[^/]+)/(?P<repo>[^/]+)/(?:blob|tree)/[^/]+/(?P<caminho>[^#?]*)(?:#(?P<ancora>.*))?$"
)


# ------------------------------------------------------------------ seleção


def e_markdown(caminho: str) -> bool:
    return caminho.lower().endswith(EXTENSOES)


def _globs(texto: str) -> list[str]:
    return [g.strip() for g in (texto or "").splitlines() if g.strip()]


def avaliar_caminho(caminho: str, modo: str, tamanho: int, incluir: str, excluir: str) -> str | None:
    """Motivo de exclusão pelo caminho, ou None se o arquivo segue para a análise de conteúdo."""
    partes = caminho.split("/")
    if modo == "120000":
        return "link_simbolico"
    if any(p in DIRETORIOS_DEPENDENCIA for p in partes[:-1]):
        return "dependencia"
    if any(fnmatch.fnmatch(caminho, g) for g in _globs(excluir)):
        return "excluido_por_filtro"
    padroes = _globs(incluir)
    if padroes and not any(fnmatch.fnmatch(caminho, g) for g in padroes):
        return "fora_do_filtro"
    if tamanho > LIMITE_BYTES:
        return "grande_demais"
    return None


def _palavras_uteis(texto: str) -> list[str]:
    sem_comentarios = re.sub(r"<!--.*?-->", " ", texto, flags=re.S)
    linhas = []
    for linha in sem_comentarios.splitlines():
        s = linha.strip()
        if not s or _TITULO.match(s) or re.fullmatch(r"(!?\[[^\]]*\]\([^)]*\)\s*)+", s):
            continue  # títulos e linhas só de badges/imagens não contam como conteúdo
        linhas.append(s)
    return re.findall(r"\w+", " ".join(linhas))


def avaliar_conteudo(texto: str) -> str:
    """Retorna 'incluido' ou o motivo de exclusão pelo conteúdo."""
    inicio = texto[:600].lower()
    if any(m in inicio for m in MARCADORES_GERADO):
        return "gerado"
    palavras = _palavras_uteis(texto)
    if len(palavras) < MIN_PALAVRAS_UTEIS:
        return "vazio"
    if len(palavras) < MIN_PALAVRAS_SEM_PLACEHOLDER:
        corpo = " ".join(palavras).lower()
        if any(t in corpo for t in TERMOS_PLACEHOLDER):
            return "placeholder"
    return "incluido"


# ------------------------------------------------------------------ seções


@dataclass
class SecaoParse:
    titulos: list[str]
    ancora: str
    linha_inicio: int
    linha_fim: int
    texto: str
    hash_conteudo: str = field(default="")


def ancora_github(titulo: str) -> str:
    texto = unicodedata.normalize("NFC", titulo).strip().lower()
    texto = re.sub(r"`|\*|_{2,}", "", texto)
    texto = re.sub(r"[^\w\- ]", "", texto)
    return texto.replace(" ", "-")


def hash_secao(titulos: list[str], texto: str) -> str:
    return hashlib.sha256(("\n".join(titulos) + "\n\n" + texto).encode("utf-8")).hexdigest()


def texto_para_embedding(titulos: list[str], texto: str) -> str:
    return (" > ".join(titulos) + "\n" + texto)[:2000]


def _blocos_brutos(linhas: list[str]):
    """Gera blocos cortando só em títulos fora de cercas de código."""
    em_codigo, cerca = False, ""
    atual = {"nivel": 0, "titulo": None, "inicio": 1, "linhas": []}
    for i, linha in enumerate(linhas, start=1):
        m_cerca = _CERCA.match(linha)
        if m_cerca:
            marca = m_cerca.group(1)
            if not em_codigo:
                em_codigo, cerca = True, marca
            elif marca[0] == cerca[0] and len(marca) >= len(cerca):
                em_codigo = False
        m_titulo = None if em_codigo or m_cerca else _TITULO.match(linha)
        if m_titulo:
            if atual["linhas"]:
                yield atual
            atual = {
                "nivel": len(m_titulo.group(1)),
                "titulo": m_titulo.group(2).strip(),
                "inicio": i,
                "linhas": [],
            }
        atual["linhas"].append(linha)
    if atual["linhas"]:
        yield atual


def _dividir_longa(linhas: list[str], inicio: int):
    """Corta seções longas em linhas em branco fora de blocos de código."""
    partes, buffer, ini_buf, tamanho = [], [], inicio, 0
    em_codigo, cerca = False, ""
    for desloc, linha in enumerate(linhas):
        m_cerca = _CERCA.match(linha)
        if m_cerca:
            marca = m_cerca.group(1)
            if not em_codigo:
                em_codigo, cerca = True, marca
            elif marca[0] == cerca[0] and len(marca) >= len(cerca):
                em_codigo = False
        buffer.append(linha)
        tamanho += len(linha) + 1
        if tamanho >= MAX_CARACTERES_SECAO and not em_codigo and not linha.strip():
            partes.append((ini_buf, buffer))
            ini_buf, buffer, tamanho = inicio + desloc + 1, [], 0
    if buffer:
        partes.append((ini_buf, buffer))
    return partes


def dividir_em_secoes(texto: str, caminho: str) -> list[SecaoParse]:
    linhas = texto.splitlines()
    pilha: list[tuple[int, str]] = []
    vistos: dict[str, int] = {}
    secoes: list[SecaoParse] = []
    nome_arquivo = posixpath.basename(caminho)

    for bloco in _blocos_brutos(linhas):
        if bloco["titulo"] is not None:
            while pilha and pilha[-1][0] >= bloco["nivel"]:
                pilha.pop()
            pilha.append((bloco["nivel"], bloco["titulo"]))
            base = ancora_github(bloco["titulo"])
            n = vistos.get(base, 0)
            vistos[base] = n + 1
            ancora = base if n == 0 else f"{base}-{n}"
            titulos = [t for _, t in pilha]
        else:
            ancora, titulos = "", [nome_arquivo]

        corpo = bloco["linhas"][1:] if bloco["titulo"] is not None else bloco["linhas"]
        if not "\n".join(corpo).strip():
            continue  # título sem conteúdo: o texto dele já está na hierarquia das seções filhas

        for ini, partes in _dividir_longa(bloco["linhas"], bloco["inicio"]):
            corpo_parte = "\n".join(partes).strip("\n")
            if not corpo_parte.strip():
                continue
            fim = ini + len(partes) - 1
            secoes.append(SecaoParse(titulos, ancora, ini, fim, corpo_parte, hash_secao(titulos, corpo_parte)))
    return secoes


def titulo_do_documento(secoes: list[SecaoParse], caminho: str) -> str:
    for s in secoes:
        if s.titulos and s.titulos[0] != posixpath.basename(caminho):
            return s.titulos[0][:300]
    return posixpath.basename(caminho)


# ------------------------------------------------------------------ links


@dataclass(frozen=True)
class AlvoLink:
    conta: str | None  # None = mesmo repositório
    repositorio: str | None
    caminho: str
    ancora: str


def extrair_links(texto: str) -> list[tuple[str, str]]:
    """Lista (alvo, linha) dos links fora de blocos de código."""
    achados, em_codigo, cerca = [], False, ""
    for linha in texto.splitlines():
        m_cerca = _CERCA.match(linha)
        if m_cerca:
            marca = m_cerca.group(1)
            if not em_codigo:
                em_codigo, cerca = True, marca
            elif marca[0] == cerca[0] and len(marca) >= len(cerca):
                em_codigo = False
            continue
        if em_codigo:
            continue
        sem_codigo_inline = re.sub(r"`[^`]*`", "", linha)
        for m in _LINK.finditer(sem_codigo_inline):
            achados.append((m.group(2), linha.strip()[:300]))
        m_ref = _REF_DEF.match(sem_codigo_inline)
        if m_ref:
            achados.append((m_ref.group(1), linha.strip()[:300]))
    return achados


def resolver_alvo(alvo: str, caminho_doc: str) -> AlvoLink | None:
    alvo = alvo.strip()
    if alvo.startswith("#"):
        return AlvoLink(None, None, caminho_doc, unquote(alvo[1:]))
    if re.match(r"^[a-z][a-z0-9+.-]*:", alvo, re.I):
        m = _GITHUB_BLOB.match(alvo)
        if not m:
            return None
        return AlvoLink(
            m.group("conta"), m.group("repo"), unquote(m.group("caminho")).strip("/"), unquote(m.group("ancora") or "")
        )
    caminho, _, ancora = alvo.partition("#")
    caminho = unquote(caminho.split("?", 1)[0])
    if caminho.startswith("/"):
        alvo_caminho = posixpath.normpath(caminho.lstrip("/"))
    else:
        alvo_caminho = posixpath.normpath(posixpath.join(posixpath.dirname(caminho_doc), caminho))
    if alvo_caminho.startswith("..") or alvo_caminho == ".":
        return None
    return AlvoLink(None, None, alvo_caminho, unquote(ancora))
